pragma solidity ^0.8.0;

import "./IArbitrator.sol";

/**
 * @title IArbitrable
 * Arbitrable interface.
 * When developing arbitrable contracts, we need to:
 * - Define the action taken when a ruling is received by the contract.
 * - Allow dispute creation. For this a function must call arbitrator.createDispute{value: _fee}(_choices,_extraData);
 */
interface IArbitrable {
    /**
     * @dev To be raised when a ruling is given.
     * @param _arbitrator The arbitrator giving the ruling.
     * @param _disputeID ID of the dispute in the Arbitrator contract.
     * @param _ruling The ruling which was given.
     */
    event Ruling(IArbitrator indexed _arbitrator, uint256 indexed _disputeID, uint256 _ruling);

    /**
     * @dev Give a ruling for a dispute. Must be called by the arbitrator.
     * The purpose of this function is to ensure that the address calling it has the right to rule on the contract.
     * @param _disputeID ID of the dispute in the Arbitrator contract.
     * @param _ruling Ruling given by the arbitrator. Note that 0 is reserved for "Not able/wanting to make a decision".
     */
    function rule(uint256 _disputeID, uint256 _ruling) external;
}

","keccak256":"0xa3eee6dd93d1df233ba3ce2d7beddeb1592a300c67dadbfc3ffb8de16c34d9e2","license":"MIT"},"contracts/common/IArbitrableProxy.sol":{"content":"// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "./IArbitrator.sol";

/**
 * @title IArbitrableProxy
 * Interface matching public/external signatures implemented in ArbiterProxy
 */
interface IArbitrableProxy {
    // ============ Enums ============
    enum DisputeType {
        Talent,
        Gig
    }

    enum DisputeStatus {
        WaitingForFreelancerFee,
        WaitingForClientFee,
        DisputeCreated,
        Resolved
    }

    // ============ Basic getters ============
    function arbitrator() external view returns (IArbitrator);

    function disputeCount() external view returns (uint256);

    // ============ Creation / fee payment / lifecycle ============
    function createDispute(
        uint256 _externalId1,
        uint256 _externalId2,
        DisputeType _disputeType,
        bytes calldata _arbitratorExtraData,
        address _freelancer,
        address _client,
        string calldata _reason
    ) external returns (uint256 localDisputeId);

    function startAndPayTalentDisputeByFreelancer(
        uint256 _talentId,
        uint256 _hiredTalentId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData,
        string calldata _reason,
        uint256 _evidenceGroupId
    ) external payable returns (uint256 localDisputeId);

    function startAndPayTalentDisputeByClient(
        uint256 _talentId,
        uint256 _hiredTalentId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData,
        string calldata _reason,
        uint256 _evidenceGroupId
    ) external payable returns (uint256 localDisputeId);

    function createAndPayGigDisputeByFreelancer(
        uint256 _gigId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData,
        string calldata _reason,
        uint256 _evidenceGroupId
    ) external payable returns (uint256 localDisputeId);

    function createAndPayGigDisputeByClient(
        uint256 _gigId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData,
        string calldata _reason,
        uint256 _evidenceGroupId
    ) external payable returns (uint256 localDisputeId);

    function payArbitrationFeeByFreelancer(
        address _caller,
        uint256 _localDisputeId,
        bytes calldata _arbitratorExtraData,
        uint256 _evidenceGroupId
    ) external payable;

    function payArbitrationFeeByClient(
        address _caller,
        uint256 _localDisputeId,
        bytes calldata _arbitratorExtraData,
        uint256 _evidenceGroupId
    ) external payable;

    function concedeDispute(uint256 _localDisputeId, uint256 _winningSide) external;

    function getDisputeStatus(uint256 _localDisputeId) external view returns (IArbitrator.DisputeStatus);

    function getCurrentRuling(uint256 _localDisputeId) external view returns (uint256);

    function hasTimedOut(uint256 _localDisputeId) external view returns (bool);

    function timeoutByInaction(uint256 _localDisputeId) external;

